import re
import numpy as np
from wordfreq import top_n_list, word_frequency

_WORDS = re.compile(r"\b[a-z]+(?:'[a-z]+)?\b")

def _tokenize(text):
    return _WORDS.findall((text or "").lower())

def _bigrams(tokens):
    return [(tokens[i], tokens[i+1]) for i in range(len(tokens) - 1)]

def _high_freq_set():
    """Calibrate on wordfreq top words at import time."""
    return set(top_n_list("en", 3000))

_TOP_FREQ = _high_freq_set()

def formulaic_bigram_cliche(text, anchor):
    tokens = _tokenize(text)
    if len(tokens) < 2:
        return 0.5

    bigrams = _bigrams(tokens)
    if not bigrams:
        return 0.5

    formulaic_count = sum(1 for w1, w2 in bigrams if w1 in _TOP_FREQ and w2 in _TOP_FREQ)
    ratio = formulaic_count / len(bigrams)

    # Invert: high formulaic ratio -> low score (clichéd is bad)
    # Scale range to [0.2, 1.0] to avoid extremes
    score = 0.2 + 0.8 * (1.0 - ratio)
    return max(0.0, min(1.0, score))

METRICS = {"formulaic_bigram_cliche": formulaic_bigram_cliche}
